interface QueryFilter {
  field: string;
  operator: 'LIKE' | '=' | '>';
  value: string;
}

private function executeFilteredQuery(filters: QueryFilter[]) {
  const conditions = filters.map((_, idx) => `${filters[idx].field} ${filters[idx].operator} ?`);
  const query = `SELECT * FROM todos WHERE ${conditions.join(' AND ')}`;
  const params = filters.map(f => f.operator === 'LIKE' ? `%${f.value}%` : f.value);
  return db.query(query, params);
}

